contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes32 h) public payable {
        uint balBefore = address(c).balance;

        bool reverted;
        c.settle(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && address(c).balance == balBefore);
    }

    receive() external payable {}
}

