pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 h) internal {
        uint balBefore = address(c).balance;
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(bytes32 h) public {
        _run(h);
    }

    receive() external payable {}
}
